CREATE TABLE ios_testflight_deployments (task_id TEXT NOT NULL, candidate_commit TEXT NOT NULL, app_id TEXT NOT NULL, attempt INTEGER NOT NULL CHECK (attempt > 0), scheme TEXT NOT NULL, bundle_id TEXT NOT NULL, marketing_version TEXT NOT NULL, build_number TEXT, upload_id TEXT, processing_status TEXT, test_group TEXT NOT NULL, membership_confirmed INTEGER CHECK (membership_confirmed IN (0, 1)), stage TEXT NOT NULL CHECK (stage IN ('prepare', 'archive', 'export', 'upload', 'processing', 'internal_testing', 'complete')), status TEXT NOT NULL CHECK (status IN ('running', 'succeeded', 'failed')), error TEXT, started_at TEXT NOT NULL, completed_at TEXT, PRIMARY KEY (task_id, candidate_commit, app_id, attempt));
CREATE INDEX idx_ios_testflight_deployments_latest ON ios_testflight_deployments (task_id, candidate_commit, app_id, attempt DESC);
CREATE INDEX idx_ios_testflight_deployments_reusable_success ON ios_testflight_deployments (task_id, candidate_commit, app_id, marketing_version, attempt DESC) WHERE status = 'succeeded' AND processing_status = 'processed' AND membership_confirmed = 1;
